`timescale 1ns/1ps
// Generated by uvmgen from the verification plan. Do not edit.
module tb;
    logic clk = 1'b0;
    logic rst_n = 1'b0;
    logic start;
    logic [15:0] a;
    logic [15:0] b;
    logic busy;
    logic exp_busy;
    bit   chk_busy;
    logic done;
    logic exp_done;
    bit   chk_done;
    logic [31:0] p;
    logic [31:0] exp_p;
    bit   chk_p;

    seq_mult #(.W(16)) dut (.clk(clk), .rst_n(rst_n), .start(start), .a(a), .b(b), .busy(busy), .done(done), .p(p));

    always #5.0 clk = ~clk;

    // ---------------- reference model ----------------
    localparam int W = 16;
    bit m_busy, m_done;
    int m_left;
    logic [15:0] m_a, m_b;
    logic [31:0] m_p;
    bit m_busy_at_reset;
    function automatic void m_reset();
        m_busy_at_reset = m_busy;
        m_busy = 0;
        m_done = 0;
        m_left = 0;
        m_a = 16'h0;
        m_b = 16'h0;
        m_p = 32'h0;
    endfunction
    function automatic void m_outputs();
        chk_busy = 1'b1;
        chk_done = 1'b1;
        chk_p = 1'b1;
        exp_busy = m_busy;
        exp_done = m_done;
        exp_p    = m_p;
    endfunction
    function automatic void m_step();
        m_done = 0;
        if (!m_busy) begin
            if (start) begin
                m_busy = 1;
                m_left = W;
                m_a = a;
                m_b = b;
            end
        end else begin
            m_left = m_left - 1;
            if (m_left == 0) begin
                m_busy = 0;
                m_done = 1;
                m_p = 32'(m_a) * 32'(m_b);
            end
        end
    endfunction

    // ---------------- sequence variables ----------------
    int i;
    logic [15:0] s_a, s_b;

    // ---------------- scoreboard + coverage ----------------
    int cov_hits [8];
    int errors = 0, checks = 0, cyc = 0;
    string cur_seq;
    task automatic check();
        m_outputs();
        checks++;
        if (chk_busy && (busy !== exp_busy)) begin
            errors++;
            if (errors <= 12)
                $display("MISMATCH cycle=%0d seq=%s i=%0d port=busy got=%0h exp=%0h | rst_n=%0b start=%0h a=%0h b=%0h", cyc, cur_seq, i, busy, exp_busy, rst_n, start, a, b);
        end
        if (chk_done && (done !== exp_done)) begin
            errors++;
            if (errors <= 12)
                $display("MISMATCH cycle=%0d seq=%s i=%0d port=done got=%0h exp=%0h | rst_n=%0b start=%0h a=%0h b=%0h", cyc, cur_seq, i, done, exp_done, rst_n, start, a, b);
        end
        if (chk_p && (p !== exp_p)) begin
            errors++;
            if (errors <= 12)
                $display("MISMATCH cycle=%0d seq=%s i=%0d port=p got=%0h exp=%0h | rst_n=%0b start=%0h a=%0h b=%0h", cyc, cur_seq, i, p, exp_p, rst_n, start, a, b);
        end
        if (start && !busy) cov_hits[0]++;
        if (start && busy) cov_hits[1]++;
        if (start && done) cov_hits[2]++;
        if (start && !busy && a == 16'h0) cov_hits[3]++;
        if (start && !busy && b == 16'h0) cov_hits[4]++;
        if (start && !busy && a == 16'hFFFF && b == 16'hFFFF) cov_hits[5]++;
        if (start && !busy && a != 16'h0 && (a & (a - 16'h1)) == 16'h0) cov_hits[6]++;
        if (!rst_n && m_busy_at_reset) cov_hits[7]++;
    endtask

    task automatic drive_defaults();
        start = 1'b0;
        a = 16'h0;
        b = 16'h0;
    endtask

    initial begin
        drive_defaults();
        rst_n = 1'b0;
        m_reset();
        repeat (3) @(negedge clk);
        rst_n = 1'b1;

        // sequence: random_products
        cur_seq = "random_products";
        for (i = 0; i < 6000; i++) begin
            @(negedge clk);
            cyc++;
            drive_defaults();
            start = 1'($urandom_range(0, 7) == 0);
            a = 16'($urandom);
            b = 16'($urandom);
            rst_n = 1'b1;
            #1;
            if (rst_n == 1'b0) m_reset();
            check();
            @(posedge clk);
            if (rst_n != 1'b0) m_step();
        end

        // sequence: corner_operands_start_held
        cur_seq = "corner_operands_start_held";
        for (i = 0; i < 408; i++) begin
            @(negedge clk);
            cyc++;
            drive_defaults();
            case ((i / 17) % 6)
                0: begin s_a = 16'h0000; s_b = 16'($urandom); end
                1: begin s_a = 16'($urandom); s_b = 16'h0000; end
                2: begin s_a = 16'hFFFF; s_b = 16'hFFFF; end
                3: begin s_a = 16'h0001; s_b = 16'($urandom); end
                4: begin s_a = 16'h1 << ((i / 102) % 16); s_b = 16'hFFFF; end
                default: begin s_a = 16'($urandom); s_b = 16'h1 << ((i / 17) % 16); end
            endcase
            start = 1'b1;
            a = s_a;
            b = s_b;
            rst_n = 1'b1;
            #1;
            if (rst_n == 1'b0) m_reset();
            check();
            @(posedge clk);
            if (rst_n != 1'b0) m_step();
        end

        // sequence: reset_while_busy
        cur_seq = "reset_while_busy";
        for (i = 0; i < 200; i++) begin
            @(negedge clk);
            cyc++;
            drive_defaults();
            start = 1'($urandom_range(0, 1));
            a = 16'($urandom);
            b = 16'($urandom);
            rst_n = ((i % 50) == 9) ? 1'b0 : 1'b1;
            #1;
            if (rst_n == 1'b0) m_reset();
            check();
            @(posedge clk);
            if (rst_n != 1'b0) m_step();
        end

        $display("COVER start_accepted %0d", cov_hits[0]);
        $display("COVER start_while_busy %0d", cov_hits[1]);
        $display("COVER back_to_back %0d", cov_hits[2]);
        $display("COVER a_zero %0d", cov_hits[3]);
        $display("COVER b_zero %0d", cov_hits[4]);
        $display("COVER both_max %0d", cov_hits[5]);
        $display("COVER a_power_of_two %0d", cov_hits[6]);
        $display("COVER reset_while_busy %0d", cov_hits[7]);
        $display("CHECKS %0d ERRORS %0d", checks, errors);
        if (errors == 0) $display("PASS"); else $display("FAIL");
        $finish;
    end
endmodule
